<script>
	import { onMount } from 'svelte';
	import { EditorCode, Tab } from '../index.js';
	import KeyValue from './key_value/kv.svelte';
	import FileUpload from '../FileUpload/index.svelte';

	let {
		data = $bindable({
			selection: 0,
			json: { code: {} },
			xml: { code: '' },
			text: {},
			form: [],
			urlencoded: []
		}),
		onchange = () => {}
	} = $props();

	//	export let data = { json: {}, xml: {}, text: {} };

	//let fnJSEditor;
	let fileName = $state('');
	let last_data = $state();

	let tabList = $state([
		{ label: 'JSON', component: tab_json },
		{ label: 'XML', disabled: false, component: tab_xml },
		{ label: 'Text', disabled: false, component: tab_text },
		{ label: 'Form', disabled: false, component: tab_form },
		{ label: 'Form-Encode', disabled: false, component: tab_form_encode },
		{ label: 'Binary', disabled: true, component: tab_binary }
	]);

	//	$: data, defaultValues();

	export function getCode() {
		//    console.log(">> getCode en JS.SVELTE ", );
		//		return fnJSEditor.getCode();
	}

	export function reset() {
		//		fnJSEditor.reset();
	}

	/*
	$effect(() => {
		data;
		console.log('Volvio a cambiar');
	});
	*/

	function defaultValues() {
		if (!data) {
			data = { selection: 0, json: { code: {} }, xml: { code: '' }, text: {} };
		}

		if (data && data.json == null) {
			data.json = { code: {} };
		}

		if (data && data.json && data.json.code == null) {
			data.json.code = {};
		}

		if (data && data.xml == null) {
			data.xml = {};
		}

		if (data && data.xml && data.xml.code == null) {
			data.xml.code = '';
		}

		if (data && data.text == null) {
			data.text = { value: '' };
		}

		if (data && data.text.value && data.text.value == null) {
			data.text.value = '';
		}

		if (data && data.selection == null) {
			data.selection = 0;
		}

		if (data && data.form == null) {
			data.form = [];
		}

		if (data && data.urlencoded == null) {
			data.urlencoded = [];
		}

		//console.log('defaultValues >> BODY =>', $state.snapshot(data));
	}

	function internalOnChange() {
		/*
		if (!equalObjs(data, last_data)) {
			console.log('internalOnChange >> BODY =>', $state.snapshot(data));
			last_data = { ...data };
			onchange(data);
		}
		*/
		//console.log('internalOnChange >> BODY =>', $state.snapshot(data));
		onchange(data);
	}

	onMount(() => {
		defaultValues();
	});
</script>

{#snippet tab_json()}
	<div>
		{#if data?.json?.code}
			<svelte:boundary onerror={(e) => console.error(e)}>
				<EditorCode
					lang="json"
					bind:code={data.json.code}
					showFormat={true}
					onchange={() => {
						//					console.log('tab_json body', data.json.code);
						internalOnChange();
					}}
				></EditorCode>

				{#snippet failed(error)}
					<div>
						<span class="icon-text">
							<span class="icon has-text-warning">
								<i class="fa-solid fa-triangle-exclamation"></i>
							</span>
							<span>{error.message}</span>
						</span>
					</div>
				{/snippet}
			</svelte:boundary>
		{/if}
	</div>
{/snippet}

{#snippet tab_xml()}
	{#if data && data.xml}
		<svelte:boundary onerror={(e) => console.error(e)}>
			<EditorCode
				lang="xml"
				bind:code={data.xml.code}
				onchange={() => {
					internalOnChange();
				}}
			></EditorCode>

			{#snippet failed(error)}
				<div>
					<span class="icon-text">
						<span class="icon has-text-warning">
							<i class="fa-solid fa-triangle-exclamation"></i>
						</span>
						<span>{error.message}</span>
					</span>
				</div>
			{/snippet}
		</svelte:boundary>
	{/if}
{/snippet}

{#snippet tab_text()}
	{#if data}
		<div>
			<div class="field">
				<!-- svelte-ignore a11y_label_has_associated_control -->
				<label class="label is-small">Content</label>
				<div class="control">
					{#if data && data.text}
						<textarea
							class="textarea is-small"
							placeholder="Content"
							bind:value={data.text.value}
							oninput={() => {
								internalOnChange();
							}}
						></textarea>
					{/if}
				</div>
			</div>
		</div>
	{/if}
{/snippet}

{#snippet tab_form_encode()}
	{#if data && data.urlencoded}
		<div>
			<KeyValue
				bind:data={data.urlencoded}
				onchange={() => {
					internalOnChange();
				}}
			></KeyValue>
		</div>
	{/if}
{/snippet}

{#snippet tab_form()}
	{#if data && data.form}
		<svelte:boundary onerror={(e) => console.error(e)}>
			<KeyValue
				enableFileType={true}
				bind:data={data.form}
				onchange={() => {
					internalOnChange();
				}}
			></KeyValue>

			{#snippet failed(error)}
				<div>
					<span class="icon-text">
						<span class="icon has-text-warning">
							<i class="fa-solid fa-triangle-exclamation"></i>
						</span>
						<span>{error.message}</span>
					</span>
				</div>
			{/snippet}
		</svelte:boundary>
	{/if}
{/snippet}

{#snippet tab_binary()}
	{#if data}
		<div>
			<FileUpload showUploadButton={false}></FileUpload>
		</div>
	{/if}
{/snippet}
{#if data}
	<Tab
		bind:tabs={tabList}
		active={data.selection}
		onselect={(r) => {
			defaultValues();
			data.selection = r.index;
		}}
	></Tab>
{/if}
